class LatticeBondMap:
    """Helper for creating consistent lattice bond indices.

    Coordinates should be supplied without manually wrapping periodic
    boundaries. Any coordinate just outside the lattice is interpreted as a
    periodic bond, which keeps length-1 and length-2 periodic bonds distinct
    from ordinary in-lattice nearest-neighbor bonds.

    Call with ``return_seen=True`` to return ``(bond, seen)`` where ``seen``
    indicates whether the same lattice bond had already been requested. Useful
    if you only want to do something to one side of a bond.
    """

    def __init__(self, Lx, Ly, Lz=None):
        self.shape = (Lx, Ly) if Lz is None else (Lx, Ly, Lz)
        self.ndim = len(self.shape)
        self._ix = defaultdict(rand_uuid)

    def wrap(self, *coos):
        wrapped_coos = []
        for coo in coos:
            coo = tuple(coo)

            if len(coo) != self.ndim:
                raise ValueError(
                    "Coordinate must match the dimensionality of the lattice."
                )

            wrapped_coos.append(tuple(x % L for x, L in zip(coo, self.shape)))

        if len(wrapped_coos) == 1:
            return wrapped_coos[0]

        return tuple(wrapped_coos)

    def _key(self, cooa, coob):
        cooa = tuple(cooa)
        coob = tuple(coob)

        if (len(cooa) != self.ndim) or (len(coob) != self.ndim):
            raise ValueError(
                "Coordinates must match the dimensionality of the lattice."
            )

        periodic_axis = None
        cooa_wrapped = []
        for axis, (a, b, L) in enumerate(zip(cooa, coob, self.shape)):
            a_inbounds = 0 <= a < L
            b_inbounds = 0 <= b < L

            if not (a_inbounds and b_inbounds):
                if periodic_axis is not None:
                    raise ValueError(
                        "Only one periodic boundary crossing is supported."
                    )
                periodic_axis = axis

            cooa_wrapped.append(a % L)

        if periodic_axis is None:
            return frozenset((cooa, coob))

        key = list(cooa_wrapped)
        key[periodic_axis] = "PBC"
        return tuple(key)

    def __call__(self, cooa, coob, *, return_seen=False):
        key = self._key(cooa, coob)
        seen = key in self._ix
        bond = self._ix[key]

        if return_seen:
            return bond, seen

        return bond


def tensor_network_align(
    *tns: "TensorNetworkGen",
    ind_ids=None,
    trace=False,
    inplace=False,
):
    r"""Align an arbitrary number of tensor networks in a stack-like geometry::

        a-a-a-a-a-a-a-a-a-a-a-a-a-a-a-a-a-a
        | | | | | | | | | | | | | | | | | | <- ind_ids[0] (defaults to 1st id)
        b-b-b-b-b-b-b-b-b-b-b-b-b-b-b-b-b-b
        | | | | | | | | | | | | | | | | | | <- ind_ids[1]
                       ...
        | | | | | | | | | | | | | | | | | | <- ind_ids[-2]
        y-y-y-y-y-y-y-y-y-y-y-y-y-y-y-y-y-y
        | | | | | | | | | | | | | | | | | | <- ind_ids[-1]
        z-z-z-z-z-z-z-z-z-z-z-z-z-z-z-z-z-z

    Parameters
    ----------
    tns : sequence of TensorNetwork
        The TNs to align, should be structured and either effective 'vectors'
        (have a ``site_ind_id``) or 'operators' (have a ``up_ind_id`` and
        ``lower_ind_id``).
    ind_ids : None, or sequence of str
        String with format specifiers to id each level of sites with. Will be
        automatically generated like ``(tns[0].site_ind_id, "__ind_a{}__",
        "__ind_b{}__", ...)`` if not given.
    inplace : bool
        Whether to modify the input tensor networks inplace.

    Returns
    -------
    tns_aligned : sequence of TensorNetwork
    """
    if not inplace:
        tns = [tn.copy() for tn in tns]

    n = len(tns)
    coordinate_formatter = get_coordinate_formatter(tns[0]._NDIMS)

    if ind_ids is None:
        if hasattr(tns[0], "site_ind_id"):
            ind_ids = [tns[0].site_ind_id]
        else:
            ind_ids = [tns[0].lower_ind_id]
        ind_ids.extend(
            f"__ind_{get_symbol(i)}{coordinate_formatter}__"
            for i in range(n - 2)
        )
    else:
        ind_ids = tuple(ind_ids)

    for i, tn in enumerate(tns):
        if hasattr(tn, "site_ind_id"):
            if i == 0:
                tn.site_ind_id = ind_ids[i]
            elif i == n - 1:
                tn.site_ind_id = ind_ids[i - 1]
            else:
                raise ValueError(
                    "An TN 'vector' can only be aligned as the "
                    "first or last TN in a sequence."
                )

        elif hasattr(tn, "upper_ind_id") and hasattr(tn, "lower_ind_id"):
            if i != 0:
                tn.upper_ind_id = ind_ids[i - 1]
            if i != n - 1:
                tn.lower_ind_id = ind_ids[i]

        else:
            raise ValueError("Can only align vectors and operators currently.")
